window.AUTH=window.AUTH||{};window.AUTH["22-174"]={"d":"22-174","id":"2022/22-174","n":"Groff v. DeJoy","briefs":[{"k":"petitioner","label":"Brief of petitioner Gerald E. Groff","date":"2023-02-21","url":"https://www.supremecourt.gov/DocketPDF/22/22-174/255164/20230327094704821_Groff%20-%20Corrected%20Merits%20Brief.pdf","side":"pet","n":75},{"k":"respondent","label":"Brief of respondent Louis DeJoy, Postmaster General, United States Postal Service","date":"2023-03-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-174/263069/20230407171128663_22-174bsUnitedStates%20CORRECTED.pdf","side":"res","n":81},{"k":"reply","label":"Reply of petitioner Gerald E. Groff","date":"2023-04-07","url":"https://www.supremecourt.gov/DocketPDF/22/22-174/263041/20230407133103835_Groff%20Reply%20for%20Petitioner.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/600us1r55_3dq4.pdf","tr":true,"items":[{"t":"case","label":"Ansonia Bd. of Educ. v. Philbrook","cite":"479 U.S. 60","y":1986,"id":"1986/85-495","sc":1,"sum":"Respondent Philbrook (hereafter respondent), a teacher employed by petitioner school board (Board), is a member of a church whose tenets require members to refrain from secular employment during designated holy days, a practice that has caused respondent to miss approximately six schooldays each year. Under pertinent collective-bargaining agreements between the Board and the teachers' union, teachers were granted …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 32","1":"19","2":"3"}},{"t":"case","label":"Barr v. Am. Ass’n of Pol. Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Brener v. Diagnostic Ctr. Hosp.","cite":"671 F.2d 141","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/671/141/","by":{"0":"41"}},{"t":"case","label":"Brown v. Davenport","cite":"142 S. Ct. 1510","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"Cent. Virginia Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Commc’ns Workers of Am. v. Beck","cite":"487 U.S. 735","y":1988,"id":"1987/86-637","sc":1,"sum":"Section 8(a)(3) of the National Labor Relations Act (NLRA) permits an employer and a union to enter into an agreement requiring all employees in the bargaining unit to pay union dues as a condition of continued employment, whether or not the employees become union members. Petitioner Communications Workers of America (CWA) entered into a collective-bargaining agreement that contains a union-security clause under …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22"}},{"t":"case","label":"Corp. of Presiding Bishop of Church of Jesus Christ of Latter-day Saints v. Amos","cite":"483 U.S. 327","y":1987,"id":"1986/86-179","sc":1,"sum":"To be valid, the state action must first promote a \"secular legislative purpose.\" The Court found that Section 702 satisfied this criterion, since it ensured that the government would not determine for religious organizations what they could count as religious activities.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Cosme v. Henderson","cite":"287 F.3d 152","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/287/152/","by":{"0":"32"}},{"t":"case","label":"Crider v. Univ. of Tenn., Knoxville","cite":"492 F. App’x 609","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/492/609/","by":{"0":"42"}},{"t":"case","label":"Page Cripe v. City of San Jose","cite":"261 F.3d 877","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/261/877/","by":{"0":"41"}},{"t":"case","label":"CRST Van Expedited, Inc. v. EEOC","cite":"578 U.S. 419","y":2016,"id":"2015/14-1375","sc":1,"sum":"The Court determined that a defendant may be a “prevailing party” for the purpose of the award of fees even without a ruling on the merits.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"0":"36","1":"24, 33","2":"13"}},{"t":"case","label":"Dewey v. Reynolds Metals Co.","cite":"429 F.2d 324","y":1970,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/429/324/","op":3,"by":{"0":"26"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"op":2,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"0":"13, 15, 23, 24, 35, 40","1":"23, 44","2":"2, 5, 11, 12, 19"}},{"t":"case","label":"Estate of Thornton v. Caldor, Inc.","cite":"472 U.S. 703","y":1985,"id":"1984/83-1158","sc":1,"sum":"The Court held 8-to-1 that the Connecticut Sabbath observance statute was void, saying its \"unyielding weighing in favor of Sabbath observers over all other interests\" results in an unconstitutional mingling of church and state.","sumSrc":"Oyez","by":{"0":"36, 37","1":"24, 33"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"Fulton v. City of Phila.","cite":"141 S. Ct. 1868","y":2021,"id":"2020/19-123","sc":1,"sum":"Philadelphia’s refusal to contract with Catholic Social Services for the provision of foster care services unless CSS agrees to certify same-sex couples as foster parents violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"Harrell v. Donahue","cite":"638 F.3d 975","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/638/975/","by":{"0":"41","1":"32"}},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"sum":"This decision overrules that portion of House v. Mayo, 324 U.S. 42, 44 (1945) (per curiam), which held that the Court lacks statutory certiorari jurisdiction to review denials of certificates of probable cause.","sumSrc":"Oyez","by":{"0":"29","1":"25","2":"7"}},{"t":"case","label":"Page Hosanna-Tabor Evangelical Lutheran Church & Sch. v. EEOC","cite":"565 U.S. 171","y":2012,"id":"2011/10-553","sc":1,"sum":"The Court found that a woman employed by a religious school who taught daily religion classes, was a commissioned minister, and regularly lead students in prayer and worship, did not have grounds to sue the school under the Ministerial Exception.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Hubbard v. United States","cite":"514 U.S. 695","y":1995,"id":"1994/94-172","sc":1,"sum":"The judgment is reversed in part. 16 F. 3d 694, reversed in part. JUSTICE STEVENS delivered the opinion of the Court with respect to Parts I, II, III, and VI, concluding that, because a federal court is neither a \"department\" nor an \"agency\" within § 1001's meaning, the statute does not apply to false statements made in judicial proceedings. Pp. 699-708, 715.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 32","2":"7"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Janus v. Am. Fed’n of State, Cnty., & Mun. Emps., Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"0":"28, 30-32","1":"26","2":"13"}},{"t":"case","label":"Johnson v. Transp. Agency","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"op":1,"sum":"The Court affirmed the promotion procedures of the Agency. Justice Brennan argued that it was not unreasonable to consider sex as one factor among many in making promotion decisions, and that the Agency's actions did not create an absolute barrier to the advancement of men (a quota system did not exist).","sumSrc":"Oyez","by":{"0":"31","1":"25","2":"8"}},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"142 S. Ct. 2407","y":2022,"id":"2021/21-418","sc":1,"op":1,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36","2":"10"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"op":3,"ar":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"0":"31, 35, 38","1":"16-18, 20, 21, 23-26","2":"7, 9, 11-13"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Page Knick v. Twp. of Scott","cite":"139 S. Ct. 2162","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33, 34","1":"20","2":"11"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"op":3,"ar":1,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"0":"35, 36"}},{"t":"case","label":"Loeffler v. Frank","cite":"486 U.S. 549","y":1988,"id":"1987/86-1431","sc":1,"sum":"Prejudgment interest may be awarded in a suit against the Postal Service brought under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"McCutcheon v. FEC","cite":"572 U.S. 185","y":2014,"id":"2013/12-536","sc":1,"sum":"The Court ruled that the two-year aggregate campaign contribution limit of the Bipartisan Campaign Reform Act was unconstitutional.","sumSrc":"Oyez","by":{"0":"30","2":"4, 5"}},{"t":"case","label":"McGowan v. Maryland","cite":"366 U.S. 420","y":1961,"id":"1960/8","sc":1,"sum":"The Court found that the blue laws did not violate the Free Exercise Clause because the employees allege only economic injury and not infringement on their own religious practices. The Court also found that the blue laws did not violate the division between church and state.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Monell v. Dep’t of Soc. Servs.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"31","1":"26","2":"6, 7, 10"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16","2":"3"}},{"t":"case","label":"Patterson v. Walgreen Co.","cite":"140 S. Ct. 685","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/685/","sc":1,"by":{"0":"4, 15, 29, 30, 17, 19, 20, 28, 29, 31","1":"15","2":"2, 1, 2, 4, 11-14"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"sum":"A nonpermanent resident seeking to cancel a lawful removal order fails to carry his burden of showing that he has not been convicted of a disqualifying offense when the statutory conviction on his record is ambiguous regarding whether a disqualifying offense formed the basis of his conviction.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"0":"29-31","1":"16, 17","2":"7"}},{"t":"case","label":"Page Riley v. Bendix Corp.","cite":"330 F. Supp. 583","y":1971,"court":"M.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp./330/583/","by":{"0":"26, 27"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Small v. Memphis Light, Gas & Water","cite":"141 S. Ct. 1227","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1227/","sc":1,"sum":"Rejecting as dicta prior “paraphrase” of Computer Fraud and Abuse Act of 1986.","sumSrc":"brief:0","by":{"0":"4, 17, 19, 30, 37"}},{"t":"case","label":"Small v. Memphis Light, Gas & Water","cite":"952 F.3d 821","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/952/821/","op":1,"by":{"0":"18, 19, 29, 30, 33, 35"}},{"t":"case","label":"Toucey v. New York Life Ins. Co.","cite":"314 U.S. 118","y":1941,"id":"scdb/1941-006","sc":1,"sum":"Section 265 of the Judicial Code forbids a federal court to enjoin a proceeding in personam in a state court on the ground that the claim in controversy has been previously -adjudicated by the federal court. P. 129. 112 F. 2d 927 and 115 F. 2d 1, reversed. No. 16 came here on certiorari, 311 U. S. 643, to review the affirmance of a decree of injunction, 112 F. 2d 927. The decision below was affirmed here by an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Trans World Airlines, Inc. v. Hardison","cite":"432 U.S. 63","y":1977,"id":"1976/75-1126","sc":1,"op":21,"sum":"Noting that Hardison “specifcally rejected” the dissent's calculations and that it is “wrong to assert” that Hardison held that a $150 cost was an undue hardship.","sumSrc":"opinion","by":{"0":"i, 3-6, 11-24, 27-38, 40, 29, 29, 40, 42","1":"3, 5, 6, 11, 15, 19, 23-25, 27-29, 34, 35, 39, 43, 46, 47","2":"1-22"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 27","1":"19"}},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"const","label":"Article I, Section 7, Clause 2","clauses":[["presentment","Presentment Clause and the Veto"]],"text":"Every Bill which shall have passed the House of Representatives and the Senate, shall, before it become a Law, be presented to the President of the United States; If he approve he shall sign it, but if not he shall return it, with his Objections to that House in which it shall have originated, who shall enter the Objections at large on their Journal, and proceed to reconsider it. If after such Reconsideration two thirds of that House shall agree to pass the Bill, it shall be sent, together with the Objections, to the other House, by which it shall likewise be reconsidered, and if approved by two thirds of that House, it shall become a Law. But in all such Cases the Votes of both Houses shall be determined by yeas and Nays, and the Names of the Persons voting for and against the Bill shall be entered on the Journal of each House respectively. If any Bill shall not be returned by the President within ten Days (Sundays excepted) after it shall have been presented to him, the Same shall be a Law, in like Manner as if he had signed it, unless the Congress by their Adjournment prevent its Return, in which Case it shall not be a Law.","by":{"0":"2"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(8)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"head":"§523. Exceptions to discharge","tname":"Bankruptcy","by":{"0":"21","1":"34"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","subs":["(r)(3)"],"stext":{"head":"§207. Maximum hours","paras":[[0,"(a) Employees engaged in interstate commerce; additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"(1) Except as otherwise provided in this section, no employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, for a workweek longer than forty hours unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(2) No employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this subsection by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966—"],[1,"(A) for a workweek longer than forty-four hours during the first year from the effective date of the Fair Labor Standards Amendments of 1966,"],[1,"(B) for a workweek longer than forty-two hours during the second year from such date, or"],[1,"(C) for a workweek longer than forty hours after the expiration of the second year from such date,"],[0,"unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(b) Employment pursuant to collective bargaining agreement; employment by independently owned and controlled local enterprise engaged in distribution of petroleum products"],[0,"No employer shall be deemed to have violated subsection (a) by employing any employee for a workweek in excess of that specified in such subsection without paying the compensation for overtime employment prescribed therein if such employee is so employed—"],[1,"(1) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that no employee shall be employed more than one thousand and forty hours during any period of twenty-six consecutive weeks; or"],[1,"(2) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that during a specified period of fifty-two consecutive weeks the employee shall be employed not more than two thousand two hundred and forty hours and shall be guaranteed not less than one thousand eight hundred and forty-hours (or not less than forty-six weeks at the normal number of hours worked per week, but not less than thirty hours per week) and not more than two thousand and eighty hours of employment for which he shall receive compensation for all hours guaranteed or worked at rates not less than those applicable under the agreement to the work performed and for all hours in excess of the guaranty which are also in excess of the maximum workweek applicable to such employee under subsection (a) or two thousand and eighty in such period at rates not less than one and one-half times the regular rate at which he is employed; or"],[1,"(3) by an independently owned and controlled local enterprise (including an enterprise with more than one bulk storage establishment) engaged in the wholesale or bulk distribution of petroleum products if—"],[2,"(A) the annual gross volume of sales of such enterprise is less than $1,000,000 exclusive of excise taxes,"],[2,"(B) more than 75 per centum of such enterprise's annual dollar volume of sales is made within the State in which such enterprise is located, and"],[2,"(C) not more than 25 per centum of the annual dollar volume of sales of such enterprise is to customers who are engaged in the bulk distribution of such products for resale,"],[1,"and such employee receives compensation for employment in excess of forty hours in any workweek at a rate not less than one and one-half times the minimum wage rate applicable to him under section 206 of this title,"],[0,"and if such employee receives compensation for employment in excess of twelve hours in any workday, or for employment in excess of fifty-six hours in any workweek, as the case may be, at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(c), (d) Repealed. Pub. L. 93–259, §19(e), Apr. 8, 1974, 88 Stat. 66"],[0,"(e) \"Regular rate\" defined"],[0,"As used in this section the \"regular rate\" at which an employee is employed shall be deemed to include all remuneration for employment paid to, or on behalf of, the employee, but shall not be deemed to include—"],[1,"(1) sums paid as gifts; payments in the nature of gifts made at Christmas time or on other special occasions, as a reward for service, the amounts of which are not measured by or dependent on hours worked, production, or efficiency;"],[1,"(2) payments made for occasional periods when no work is performed due to vacation, holiday, illness, failure of the employer to provide sufficient work, or other similar cause; reasonable payments for traveling expenses, or other expenses, incurred by an employee in the furtherance of his employer's interests and properly reimbursable by the employer; and other similar payments to an employee which are not made as compensation for his hours of employment;"],[1,"(3) Sums 1 paid in recognition of services performed during a given period if either, (a) both the fact that payment is to be made and the amount of the payment are determined at the sole discretion of the employer at or near the end of the period and not pursuant to any prior contract, agreement, or promise causing the employee to expect such payments regularly; or (b) the payments are made pursuant to a bona fide profit-sharing plan or trust or bona fide thrift or savings plan, meeting the requirements of the Administrator set forth in appropriate regulations which he shall issue, having due regard among other relevant factors, to the extent to which the amounts paid to the employee are determined without regard to hours of work, production, or efficiency; or (c) the payments are talent fees (as such talent fees are defined and delimited by regulations of the Administrator) paid to performers, including announcers, on radio and television programs;"],[1,"(4) contributions irrevocably made by an employer to a trustee or third person pursuant to a bona fide plan for providing old-age, retirement, life, accident, or health insurance or similar benefits for employees;"],[1,"(5) extra compensation provided by a premium rate paid for certain hours worked by the employee in any day or workweek because such hours are hours worked in excess of eight in a day or in excess of the maximum workweek applicable to such employee under subsection (a) or in excess of the employee's normal working hours or regular working hours, as the case may be;"],[1,"(6) extra compensation provided by a premium rate paid for work by the employee on Saturdays, Sundays, holidays, or regular days of rest, or on the sixth or seventh day of the workweek, where such premium rate is not less than one and one-half times the rate established in good faith for like work performed in nonovertime hours on other days;"],[1,"(7) extra compensation provided by a premium rate paid to the employee, in pursuance of an applicable employment contract or collective-bargaining agreement, for work outside of the hours established in good faith by the contract or agreement as the basic, normal, or regular workday (not exceeding eight hours) or workweek (not exceeding the maximum workweek applicable to such employee under subsection (a),2 where such premium rate is not less than one and one-half times the rate established in good faith by the contract or agreement for like work performed during such workday or workweek; or"],[1,"(8) any value or income derived from employer-provided grants or rights provided pursuant to a stock option, stock appreciation right, or bona fide employee stock purchase program which is not otherwise excludable under any of paragraphs (1) through (7) if—"],[2,"(A) grants are made pursuant to a program, the terms and conditions of which are communicated to participating employees either at the beginning of the employee's participation in the program or at the time of the grant;"],[2,"(B) in the case of stock options and stock appreciation rights, the grant or right cannot be exercisable for a period of at least 6 months after the time of grant (except that grants or rights may become exercisable because of an employee's death, disability, retirement, or a change in corporate ownership, or other circumstances permitted by regulation), and the exercise price is at least 85 percent of the fair market value of the stock at the time of grant;"],[2,"(C) exercise of any grant or right is voluntary; and"],[2,"(D) any determinations regarding the award of, and the amount of, employer-provided grants or rights that are based on performance are—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/207?type=usc&year=mostrecent&link-type=html"},"head":"§207. Maximum hours","tname":"Labor","by":{"0":"21","1":"36"}},{"t":"usc","label":"38 U.S.C. § 4303","url":"https://www.law.cornell.edu/uscode/text/38/4303","subs":["(10)","(16)"],"stext":{"head":"§4303. Definitions","paras":[[0,"For the purposes of this chapter—"],[1,"(1) The term \"Attorney General\" means the Attorney General of the United States or any person designated by the Attorney General to carry out a responsibility of the Attorney General under this chapter."],[1,"(2) The term \"benefit\", \"benefit of employment\", or \"rights and benefits\" means the terms, conditions, or privileges of employment, including any advantage, profit, privilege, gain, status, account, or interest (including wages or salary for work performed) that accrues by reason of an employment contract or agreement or an employer policy, plan, or practice and includes rights and benefits under a pension plan, a health plan, an employee stock ownership plan, insurance coverage and awards, bonuses, severance pay, supplemental unemployment benefits, vacations, and the opportunity to select work hours or location of employment."],[1,"(3) The term \"employee\" means any person employed by an employer. Such term includes any person who is a citizen, national, or permanent resident alien of the United States employed in a workplace in a foreign country by an employer that is an entity incorporated or otherwise organized in the United States or that is controlled by an entity organized in the United States, within the meaning of section 4319(c) of this title."],[1,"(4)(A) Except as provided in subparagraphs (B) and (C), the term \"employer\" means any person, institution, organization, or other entity that pays salary or wages for work performed or that has control over employment opportunities, including—"],[2,"(i) a person, institution, organization, or other entity to whom the employer has delegated the performance of employment-related responsibilities;"],[2,"(ii) the Federal Government;"],[2,"(iii) a State;"],[2,"(iv) any successor in interest to a person, institution, organization, or other entity referred to in this subparagraph; and"],[2,"(v) a person, institution, organization, or other entity that has denied initial employment in violation of section 4311."],[1,"(B) In the case of a National Guard technician employed under section 709 of title 32, the term \"employer\" means the adjutant general of the State in which the technician is employed."],[1,"(C) Except as an actual employer of employees, an employee pension benefit plan described in section 3(2) of the Employee Retirement Income Security Act of 1974 (29 U.S.C. 1002(2)) shall be deemed to be an employer only with respect to the obligation to provide benefits described in section 4318."],[1,"(D)(i) Whether the term \"successor in interest\" applies with respect to an entity described in subparagraph (A) for purposes of clause (iv) of such subparagraph shall be determined on a case-by-case basis using a multi-factor test that considers the following factors:"],[2,"(I) Substantial continuity of business operations."],[2,"(II) Use of the same or similar facilities."],[2,"(III) Continuity of work force."],[2,"(IV) Similarity of jobs and working conditions."],[2,"(V) Similarity of supervisory personnel."],[2,"(VI) Similarity of machinery, equipment, and production methods."],[2,"(VII) Similarity of products or services."],[1,"(ii) The entity's lack of notice or awareness of a potential or pending claim under this chapter at the time of a merger, acquisition, or other form of succession shall not be considered when applying the multi-factor test under clause (i)."],[1,"(5) The term \"Federal executive agency\"—"],[2,"(A) except as provided in subparagraph (B), includes—"],[3,"(i) the United States Postal Service;"],[3,"(ii) the Postal Regulatory Commission;"],[3,"(iii) any nonappropriated fund instrumentality of the United States;"],[3,"(iv) any Executive agency (as defined in section 105 of title 5); and"],[3,"(v) any military department (as defined in section 102 of title 5) with respect to the civilian employees of that department; and"],[2,"(B) does not include—"],[3,"(i) an agency referred to in section 2302(a)(2)(C)(ii) of title 5;"],[3,"(ii) the National Oceanic and Atmospheric Administration with respect to members of the commissioned officer corps of the National Oceanic and Atmospheric Administration; or"],[3,"(iii) the Public Health Service with respect to members of the Commissioned Corps of the Public Health Service serving on active duty, active duty for training, or inactive duty training."],[1,"(6) The term \"Federal Government\" includes any Federal executive agency, the legislative branch of the United States, and the judicial branch of the United States."],[1,"(7) The term \"health plan\" means an insurance policy or contract, medical or hospital service agreement, membership or subscription contract, or other arrangement under which health services for individuals are provided or the expenses of such services are paid."],[1,"(8) The term \"notice\" means (with respect to subchapter II) any written or verbal notification of an obligation or intention to perform service in the uniformed services provided to an employer by the employee who will perform such service or by the uniformed service in which such service is to be performed."],[1,"(9) The term \"qualified\", with respect to an employment position, means having the ability to perform the essential tasks of the position."],[1,"(10) The term \"reasonable efforts\", in the case of actions required of an employer under this chapter, means actions, including training provided by an employer, that do not place an undue hardship on the employer."],[1,"(11) Notwithstanding section 101, the term \"Secretary\" means the Secretary of Labor or any person designated by such Secretary to carry out an activity under this chapter."],[1,"(12) The term \"seniority\" means longevity in employment together with any benefits of employment which accrue with, or are determined by, longevity in employment."],[1,"(13) The term \"service in the uniformed services\" means the performance of duty on a voluntary or involuntary basis in a uniformed service under competent authority and includes active duty, active duty for training, initial active duty for training, inactive duty training, full-time National Guard duty, State active duty for a period of 14 days or more, State active duty in response to a national emergency declared by the President under the National Emergencies Act (50 U.S.C. 1601 et seq.), State active duty in response to a major disaster declared by the President under section 401 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5170), a period for which a person is absent from a position of employment for the purpose of an examination to determine the fitness of the person to perform any such duty, a period for which a System member of the National Urban Search and Rescue Response System is absent from a position of employment due to an appointment into Federal service under section 327 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act, a period for which a person is absent from a position of employment due to an appointment into service in the Federal Emergency Management Agency as intermittent personnel under section 306(b)(1) of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5149(b)(1)), and a period for which a person is absent from employment for the purpose of performing funeral honors duty as authorized by section 12503 of title 10 or section 115 of title 32."],[1,"(14) The term \"State\" means each of the several States of the United States, the District of Columbia, the Commonwealth of Puerto Rico, Guam, the Virgin Islands, and other territories of the United States (including the agencies and political subdivisions thereof)."],[1,"(15) The term \"State active duty\" means training or other duty, other than inactive duty, performed by a member of the National Guard of a State—"],[2,"(A) not under section 502 of title 32 or under title 10;"],[2,"(B) in service to the Governor of a State; and"],[2,"(C) for which the member is not entitled to pay from the Federal Government."],[1,"(16) The term \"undue hardship\", in the case of actions taken by an employer, means actions requiring significant difficulty or expense, when considered in light of—"],[2,"(A) the nature and cost of the action needed under this chapter;"],[2,"(B) the overall financial resources of the facility or facilities involved in the provision of the action; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such action upon the operation of the facility;"],[2,"(C) the overall financial resources of the employer; the overall size of the business of an employer with respect to the number of its employees; the number, type, and location of its facilities; and"],[2,"(D) the type of operation or operations of the employer, including the composition, structure, and functions of the work force of such employer; the geographic separateness, administrative, or fiscal relationship of the facility or facilities in question to the employer."],[1,"(17) The term \"uniformed services\" means the Armed Forces, the Army National Guard and the Air National Guard when engaged in active duty for training, inactive duty training, or full-time National Guard duty, the Commissioned Corps of the Public Health Service, the commissioned officer corps of the National Oceanic and Atmospheric Administration, System members of the National Urban Search and Rescue Response System during a period of appointment into Federal service under section 327 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act, intermittent personnel who are appointed into Federal Emergency Management Agency service under section 306(b)(1) of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5149(b)(1)) or to train for such service, and any other category of persons designated by the President in time of war or national emergency."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/4303?type=usc&year=mostrecent&link-type=html"},"head":"§4303. Definitions","tname":"Veterans' Benefits","by":{"0":"21, 21","1":"36"}},{"t":"usc","label":"38 U.S.C. § 4312","url":"https://www.law.cornell.edu/uscode/text/38/4312","subs":["(d)"],"by":{"0":"21"}},{"t":"usc","label":"38 U.S.C. § 4313","url":"https://www.law.cornell.edu/uscode/text/38/4313","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(j)"],"stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"i, 2, 3, 5, 14, 39","1":"2-5, 10, 12, 13, 15, 18, 19, 21, 24, 25, 27, 28, 33-38, 40, 41, 44, 46, 47, 47","2":"8, 18"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)","(a)(1)","(h)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"i, 1, 2, 4, 5","1":"47, 47, 47","2":"8, 21"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(a)"],"stext":{"head":"§2000e–16. Employment by Federal Government","paras":[[0,"(a) Discriminatory practices prohibited; employees or applicants for employment subject to coverage"],[0,"All personnel actions affecting employees or applicants for employment (except with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units of the Government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on race, color, religion, sex, or national origin."],[0,"(b) Equal Employment Opportunity Commission; enforcement powers; issuance of rules, regulations, etc.; annual review and approval of national and regional equal employment opportunity plans; review and evaluation of equal employment opportunity programs and publication of progress reports; consultations with interested parties; compliance with rules, regulations, etc.; contents of national and regional equal employment opportunity plans; authority of Librarian of Congress"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission shall have authority to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without back pay, as will effectuate the policies of this section, and shall issue such rules, regulations, orders and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the annual review and approval of a national and regional equal employment opportunity plan which each department and agency and each appropriate unit referred to in subsection (a) of this section shall submit in order to maintain an affirmative program of equal employment opportunity for all such employees and applicants for employment;"],[1,"(2) be responsible for the review and evaluation of the operation of all agency equal employment opportunity programs, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each such department, agency, or unit; and"],[1,"(3) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to equal employment opportunity."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. The plan submitted by each department, agency, and unit shall include, but not be limited to—"],[1,"(1) provision for the establishment of training and education programs designed to provide a maximum opportunity for employees to advance so as to perform at their highest potential; and"],[1,"(2) a description of the qualifications in terms of training and experience relating to equal employment opportunity for the principal and operating officials of each such department, agency, or unit responsible for carrying out the equal employment opportunity program and of the allocation of personnel and resources proposed by such department, agency, or unit to carry out its equal employment opportunity program."],[0,"With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil action by employee or applicant for employment for redress of grievances; time for bringing of action; head of department, agency, or unit as defendant"],[0,"Within 90 days of receipt of notice of final action taken by a department, agency, or unit referred to in subsection (a), or by the Equal Employment Opportunity Commission upon an appeal from a decision or order of such department, agency, or unit on a complaint of discrimination based on race, color, religion, sex or national origin, brought pursuant to subsection (a) of this section, Executive Order 11478 or any succeeding Executive orders, or after one hundred and eighty days from the filing of the initial charge with the department, agency, or unit or with the Equal Employment Opportunity Commission on appeal from a decision or order of such department, agency, or unit until such time as final action may be taken by a department, agency, or unit, an employee or applicant for employment, if aggrieved by the final disposition of his complaint, or by the failure to take final action on his complaint, may file a civil action as provided in section 2000e–5 of this title, in which civil action the head of the department, agency, or unit, as appropriate, shall be the defendant."],[0,"(d) Section 2000e–5(f) through (k) of this title applicable to civil actions"],[0,"The provisions of section 2000e–5(f) through (k) of this title, as applicable, shall govern civil actions brought hereunder, and the same interest to compensate for delay in payment shall be available as in cases involving nonpublic parties..1"],[0,"(e) Government agency or official not relieved of responsibility to assure nondiscrimination in employment or equal employment opportunity"],[0,"Nothing contained in this Act shall relieve any Government agency or official of its or his primary responsibility to assure nondiscrimination in employment as required by the Constitution and statutes or of its or his responsibilities under Executive Order 11478 relating to equal employment opportunity in the Federal Government."],[0,"(f) Section 2000e–5(e)(3) of this title applicable to compensation discrimination"],[0,"Section 2000e–5(e)(3) of this title shall apply to complaints of discrimination in compensation under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-16?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–16. Employment by Federal Government","tname":"The Public Health and Welfare","by":{"0":"5","1":"18"}},{"t":"usc","label":"42 U.S.C. § 12111","url":"https://www.law.cornell.edu/uscode/text/42/12111","subs":["(10)","(9)","(10)(A)"],"stext":{"head":"§12111. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Commission"],[1,"The term \"Commission\" means the Equal Employment Opportunity Commission established by section 2000e–4 of this title."],[0,"(2) Covered entity"],[1,"The term \"covered entity\" means an employer, employment agency, labor organization, or joint labor-management committee."],[0,"(3) Direct threat"],[1,"The term \"direct threat\" means a significant risk to the health or safety of others that cannot be eliminated by reasonable accommodation."],[0,"(4) Employee"],[1,"The term \"employee\" means an individual employed by an employer. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[0,"(5) Employer"],[0,"(A) In general"],[2,"The term \"employer\" means a person engaged in an industry affecting commerce who has 15 or more employees for each working day in each of 20 or more calendar weeks in the current or preceding calendar year, and any agent of such person, except that, for two years following the effective date of this subchapter, an employer means a person engaged in an industry affecting commerce who has 25 or more employees for each working day in each of 20 or more calendar weeks in the current or preceding year, and any agent of such person."],[0,"(B) Exceptions"],[2,"The term \"employer\" does not include—"],[3,"(i) the United States, a corporation wholly owned by the government of the United States, or an Indian tribe; or"],[3,"(ii) a bona fide private membership club (other than a labor organization) that is exempt from taxation under section 501(c) of title 26."],[0,"(6) Illegal use of drugs"],[0,"(A) In general"],[2,"The term \"illegal use of drugs\" means the use of drugs, the possession or distribution of which is unlawful under the Controlled Substances Act [21 U.S.C. 801 et seq.]. Such term does not include the use of a drug taken under supervision by a licensed health care professional, or other uses authorized by the Controlled Substances Act or other provisions of Federal law."],[0,"(B) Drugs"],[2,"The term \"drug\" means a controlled substance, as defined in schedules I through V of section 202 of the Controlled Substances Act [21 U.S.C. 812]."],[0,"(7) Person, etc."],[1,"The terms \"person\", \"labor organization\", \"employment agency\", \"commerce\", and \"industry affecting commerce\", shall have the same meaning given such terms in section 2000e of this title."],[0,"(8) Qualified individual"],[1,"The term \"qualified individual\" means an individual who, with or without reasonable accommodation, can perform the essential functions of the employment position that such individual holds or desires. For the purposes of this subchapter, consideration shall be given to the employer's judgment as to what functions of a job are essential, and if an employer has prepared a written description before advertising or interviewing applicants for the job, this description shall be considered evidence of the essential functions of the job."],[0,"(9) Reasonable accommodation"],[1,"The term \"reasonable accommodation\" may include—"],[2,"(A) making existing facilities used by employees readily accessible to and usable by individuals with disabilities; and"],[2,"(B) job restructuring, part-time or modified work schedules, reassignment to a vacant position, acquisition or modification of equipment or devices, appropriate adjustment or modifications of examinations, training materials or policies, the provision of qualified readers or interpreters, and other similar accommodations for individuals with disabilities."],[0,"(10) Undue hardship"],[0,"(A) In general"],[2,"The term \"undue hardship\" means an action requiring significant difficulty or expense, when considered in light of the factors set forth in subparagraph (B)."],[0,"(B) Factors to be considered"],[2,"In determining whether an accommodation would impose an undue hardship on a covered entity, factors to be considered include—"],[3,"(i) the nature and cost of the accommodation needed under this chapter;"],[3,"(ii) the overall financial resources of the facility or facilities involved in the provision of the reasonable accommodation; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such accommodation upon the operation of the facility;"],[3,"(iii) the overall financial resources of the covered entity; the overall size of the business of a covered entity with respect to the number of its employees; the number, type, and location of its facilities; and"],[3,"(iv) the type of operation or operations of the covered entity, including the composition, structure, and functions of the workforce of such entity; the geographic separateness, administrative, or fiscal relationship of the facility or facilities in question to the covered entity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12111?type=usc&year=mostrecent&link-type=html"},"head":"§12111. Definitions","tname":"The Public Health and Welfare","by":{"0":"20","1":"34, 34","2":"18"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","subs":["(b)(5)(A)"],"stext":{"head":"§12112. Discrimination","paras":[[0,"(a) General rule"],[0,"No covered entity shall discriminate against a qualified individual on the basis of disability in regard to job application procedures, the hiring, advancement, or discharge of employees, employee compensation, job training, and other terms, conditions, and privileges of employment."],[0,"(b) Construction"],[0,"As used in subsection (a), the term \"discriminate against a qualified individual on the basis of disability\" includes—"],[1,"(1) limiting, segregating, or classifying a job applicant or employee in a way that adversely affects the opportunities or status of such applicant or employee because of the disability of such applicant or employee;"],[1,"(2) participating in a contractual or other arrangement or relationship that has the effect of subjecting a covered entity's qualified applicant or employee with a disability to the discrimination prohibited by this subchapter (such relationship includes a relationship with an employment or referral agency, labor union, an organization providing fringe benefits to an employee of the covered entity, or an organization providing training and apprenticeship programs);"],[1,"(3) utilizing standards, criteria, or methods of administration—"],[2,"(A) that have the effect of discrimination on the basis of disability; or"],[2,"(B) that perpetuate the discrimination of others who are subject to common administrative control;"],[1,"(4) excluding or otherwise denying equal jobs or benefits to a qualified individual because of the known disability of an individual with whom the qualified individual is known to have a relationship or association;"],[1,"(5)(A) not making reasonable accommodations to the known physical or mental limitations of an otherwise qualified individual with a disability who is an applicant or employee, unless such covered entity can demonstrate that the accommodation would impose an undue hardship on the operation of the business of such covered entity; or"],[1,"(B) denying employment opportunities to a job applicant or employee who is an otherwise qualified individual with a disability, if such denial is based on the need of such covered entity to make reasonable accommodation to the physical or mental impairments of the employee or applicant;"],[1,"(6) using qualification standards, employment tests or other selection criteria that screen out or tend to screen out an individual with a disability or a class of individuals with disabilities unless the standard, test or other selection criteria, as used by the covered entity, is shown to be job-related for the position in question and is consistent with business necessity; and"],[1,"(7) failing to select and administer tests concerning employment in the most effective manner to ensure that, when such test is administered to a job applicant or employee who has a disability that impairs sensory, manual, or speaking skills, such test results accurately reflect the skills, aptitude, or whatever other factor of such applicant or employee that such test purports to measure, rather than reflecting the impaired sensory, manual, or speaking skills of such employee or applicant (except where such skills are the factors that the test purports to measure)."],[0,"(c) Covered entities in foreign countries"],[0,"(1) In general"],[1,"It shall not be unlawful under this section for a covered entity to take any action that constitutes discrimination under this section with respect to an employee in a workplace in a foreign country if compliance with this section would cause such covered entity to violate the law of the foreign country in which such workplace is located."],[0,"(2) Control of corporation"],[0,"(A) Presumption"],[2,"If an employer controls a corporation whose place of incorporation is a foreign country, any practice that constitutes discrimination under this section and is engaged in by such corporation shall be presumed to be engaged in by such employer."],[0,"(B) Exception"],[2,"This section shall not apply with respect to the foreign operations of an employer that is a foreign person not controlled by an American employer."],[0,"(C) Determination"],[2,"For purposes of this paragraph, the determination of whether an employer controls a corporation shall be based on—"],[3,"(i) the interrelation of operations;"],[3,"(ii) the common management;"],[3,"(iii) the centralized control of labor relations; and"],[3,"(iv) the common ownership or financial control,"],[2,"of the employer and the corporation."],[0,"(d) Medical examinations and inquiries"],[0,"(1) In general"],[1,"The prohibition against discrimination as referred to in subsection (a) shall include medical examinations and inquiries."],[0,"(2) Preemployment"],[0,"(A) Prohibited examination or inquiry"],[2,"Except as provided in paragraph (3), a covered entity shall not conduct a medical examination or make inquiries of a job applicant as to whether such applicant is an individual with a disability or as to the nature or severity of such disability."],[0,"(B) Acceptable inquiry"],[2,"A covered entity may make preemployment inquiries into the ability of an applicant to perform job-related functions."],[0,"(3) Employment entrance examination"],[1,"A covered entity may require a medical examination after an offer of employment has been made to a job applicant and prior to the commencement of the employment duties of such applicant, and may condition an offer of employment on the results of such examination, if—"],[2,"(A) all entering employees are subjected to such an examination regardless of disability;"],[2,"(B) information obtained regarding the medical condition or history of the applicant is collected and maintained on separate forms and in separate medical files and is treated as a confidential medical record, except that—"],[3,"(i) supervisors and managers may be informed regarding necessary restrictions on the work or duties of the employee and necessary accommodations;"],[3,"(ii) first aid and safety personnel may be informed, when appropriate, if the disability might require emergency treatment; and"],[3,"(iii) government officials investigating compliance with this chapter shall be provided relevant information on request; and"],[2,"(C) the results of such examination are used only in accordance with this subchapter."],[0,"(4) Examination and inquiry"],[0,"(A) Prohibited examinations and inquiries"],[2,"A covered entity shall not require a medical examination and shall not make inquiries of an employee as to whether such employee is an individual with a disability or as to the nature or severity of the disability, unless such examination or inquiry is shown to be job-related and consistent with business necessity."],[0,"(B) Acceptable examinations and inquiries"],[2,"A covered entity may conduct voluntary medical examinations, including voluntary medical histories, which are part of an employee health program available to employees at that work site. A covered entity may make inquiries into the ability of an employee to perform job-related functions."],[0,"(C) Requirement"],[2,"Information obtained under subparagraph (B) regarding the medical condition or history of any employee are subject to the requirements of subparagraphs (B) and (C) of paragraph (3)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12112?type=usc&year=mostrecent&link-type=html"},"head":"§12112. Discrimination","tname":"The Public Health and Welfare","by":{"0":"20","2":"18, 20"}},{"t":"law","label":"Pub. L. No. 88-352","url":"https://www.govinfo.gov/link/statute/78/241","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 92-261","url":"https://www.govinfo.gov/link/statute/86/103","by":{"0":"4","1":"5"}},{"t":"law","label":"Pregnant Workers Fairness Act, Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"0":"20, 43","1":"36"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","subs":["(b)(3)(ii)","(b)(3)(A)(ii)"],"by":{"0":"22","1":"34"}},{"t":"reg","label":"29 C.F.R. § 1605.2","url":"https://www.ecfr.gov/current/title-29/section-1605.2","by":{"0":"19, 25"}},{"t":"reg","label":"29 C.F.R. § 1605.3","url":"https://www.ecfr.gov/current/title-29/section-1605.3","by":{"0":"25"}},{"t":"reg","label":"29 C.F.R. pt. 1605","url":"https://www.ecfr.gov/current/title-29/part-1605","by":{"0":"25"}},{"t":"reg","label":"29 C.F.R. pt. 1630","url":"https://www.ecfr.gov/current/title-29/part-1630","by":{"0":"42"}},{"t":"reg","label":"31 Fed. Reg. 8370","url":"https://www.govinfo.gov/link/fr/31/8370","by":{"0":"25"}},{"t":"reg","label":"32 Fed. Reg. 10298","url":"https://www.govinfo.gov/link/fr/32/10298","by":{"0":"25, 40","1":"4, 35","2":"16"}},{"t":"case","label":"Zablotsky, After the Fall: The Employer’s Duty to Accommodate Religious Practices under Title VII after Ansonia Board of Education v. Philbrook","cite":"50 U. Pitt. L. Rev. 513","y":1989,"url":"https://www.courtlistener.com/c/U.%20Pitt.%20L.%20Rev./50/513/","by":{"0":"33"}},{"t":"case","label":"Adeyeye v. Heartland Sweeteners, LLC","cite":"721 F.3d 444","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/721/444/","op":2,"by":{"1":"30, 33, 39"}},{"t":"case","label":"Antoine v. First Student, Inc.","cite":"713 F.3d 824","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/713/824/","by":{"1":"31"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Brown v. General Motors Corp.","cite":"601 F.2d 956","y":1979,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/601/956/","by":{"1":"31"}},{"t":"case","label":"Brown v. Polk Cnty.","cite":"61 F.3d 650","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/61/650/","by":{"1":"40, 46"}},{"t":"case","label":"Bruff v. North Miss. Health Servs., Inc.","cite":"244 F.3d 495","y":2001,"url":"https://www.courtlistener.com/c/F.3d/244/495/","by":{"1":"31, 32"}},{"t":"case","label":"Cassell v. Skywest, Inc.","cite":"2022 WL 375855","y":2022,"court":"D. Utah Feb. 8","by":{"1":"22"}},{"t":"case","label":"Crider v. University of Tenn.","cite":"492 Fed. Appx. 609","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./492/609/","by":{"1":"30, 33"}},{"t":"case","label":"Davis v. Fort Bend Cnty.","cite":"765 F.3d 480","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/765/480/","by":{"1":"31"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Org.","cite":"142 S. Ct. 2228","y":2022,"id":"2021/19-1392","sc":1,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20","2":"10"}},{"t":"case","label":"EEOC v. Greyhound Lines, Inc.","cite":"554 F. Supp. 3d 739","y":2021,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/554/739/","by":{"1":"27"}},{"t":"case","label":"EEOC v. Townley Eng’g & Mfg. Co.","cite":"859 F.2d 610","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/859/610/","by":{"1":"30"}},{"t":"case","label":"Enriquez v. Gemini Motor Transport LP","cite":"2021 WL 5908208","y":2021,"court":"D. Ariz. Dec. 14","by":{"1":"23","2":"11"}},{"t":"case","label":"Getz v. Pennsylvania, Dep’t of Pub. Welfare","cite":"802 F.2d 72","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/802/72/","by":{"1":"48","2":"21"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"1":"16, 38","2":"16"}},{"t":"case","label":"Hardison v. Trans World Airlines, Inc.","cite":"375 F. Supp. 877","y":1974,"court":"W.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./375/877/","op":2,"by":{"1":"28"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"1":"16, 27"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"op":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"1":"20","2":"10"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38","2":"16"}},{"t":"case","label":"Lee v. ABF Freight Sys., Inc.","cite":"22 F.3d 1019","y":1994,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/22/1019/","by":{"1":"48","2":"21"}},{"t":"case","label":"Leegin Creative Leather Prods., Inc. v. PSKS, Inc.","cite":"551 U.S. 877","y":2007,"id":"2006/06-480","sc":1,"sum":"The Court ruled 5-4 that \" Dr. Miles should be overruled and that vertical price restraints are to be judged by the rule of reason.\" Justice Anthony Kennedy's majority opinion held that Dr. Miles had erred by treating vertical minimum price agreements between manufacturers and retailers as analogous to horizontal price-fixing agreements between sellers.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Logan v. Organic Harvest, LLC","cite":"2020 WL 1547985","y":2020,"court":"N.D. Ala. Apr. 1","by":{"1":"23"}},{"t":"case","label":"Mann v. Frank","cite":"7 F.3d 1365","y":1993,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/7/1365/","by":{"1":"32"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Mohamed v. 1st Class Staffing, LLC","cite":"286 F. Supp. 3d 884","y":2017,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/286/884/","by":{"1":"27"}},{"t":"case","label":"Opuku-Boateng v. California","cite":"95 F.3d 1461","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/95/1461/","by":{"1":"31, 32, 40, 46"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Peterson v. Hewlett-Packard Co.","cite":"358 F.3d 599","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/358/599/","by":{"1":"45"}},{"t":"case","label":"Protos v. Volkswagen of Am., Inc.","cite":"797 F.2d 129","y":1986,"url":"https://www.courtlistener.com/c/F.2d/797/129/","by":{"1":"31, 32"}},{"t":"case","label":"Rasul v. Bush","cite":"542 U.S. 466","y":2004,"id":"2003/03-334","sc":1,"sum":"The Court ruled that United States courts have jurisdiction to consider legal appeals filed on behalf of foreign citizens held by the United States military in Guantanamo Bay Naval Base, Cuba.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Reyazuddin v. Montgomery Cnty.","cite":"789 F.3d 407","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/789/407/","by":{"1":"37"}},{"t":"case","label":"Rivas v. Caesars Enters. Servs., LLC","cite":"2021 WL 3572659","y":2021,"court":"D. Nev. Aug. 11","by":{"1":"23"}},{"t":"case","label":"Searls v. Johns Hopkins Hosp.","cite":"158 F. Supp. 3d 427","y":2016,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/158/427/","by":{"1":"37"}},{"t":"case","label":"Slocum v. Devezin","cite":"948 F. Supp. 2d 661","y":2013,"court":"E.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/948/661/","by":{"1":"32"}},{"t":"case","label":"Smith v. Pyro Mining Co.","cite":"827 F.2d 1081","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/827/1081/","by":{"1":"30"}},{"t":"case","label":"South Dakota v. Wayfair, Inc.","cite":"138 S. Ct. 2080","y":2018,"id":"2017/17-494","sc":1,"sum":"A case in which the Court overruled Quill Corp. v. North Dakota and National Bellas Hess, Inc. v. Department of Revenue of Illinois, holding that states may require sellers with no physical presence in the state to collect and remit sales tax for goods sold within the state.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Square D Co. v. Niagara Frontier Tariff Bureau, Inc.","cite":"476 U.S. 409","y":1986,"id":"1985/85-21","sc":1,"sum":"The Supreme Court held that the precedent established by the previous decision is relevant to this case because in both cases the rates were approved by the ICC, which meant that the rates were lawful under the Interstate Commerce Act, and the carriers were protected from suits for damages. The Court also held that the recently enacted Reed-Bullwinkle Act did not alter any anti-trust laws applicable to carriers.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Sutton v. DirecTV LLC","cite":"2022 WL 808692","y":2022,"court":"N.D. Ala. Mar. 16","by":{"1":"22","2":"11"}},{"t":"case","label":"Tetzlaff v. Educational Credit Mgmt. Corp.","cite":"794 F.3d 756","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/756/","by":{"1":"34"}},{"t":"case","label":"US Airways, Inc. v. Barnett","cite":"535 U.S. 391","y":2002,"id":"2001/00-1250","sc":1,"sum":"The Court held that the ADA did not require the employer to assign the employee to the mailroom position in violation of the established seniority system. The Court reasoned that an employer's showing that a requested accommodation conflicts with seniority rules is ordinarily sufficient to show that an accommodation is not reasonable.","sumSrc":"Oyez","by":{"1":"35, 42","2":"21"}},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"by":{"1":"17"}},{"t":"case","label":"Williams v. United States Steel Corp.","cite":"40 F. Supp. 3d 1055","y":2014,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/40/1055/","by":{"1":"32"}},{"t":"case","label":"Wisconsin Cent, Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"37"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"24, 33"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"1":"13"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(b)","(f)(1)"],"by":{"1":"21, 21"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"1":"36"}},{"t":"law","label":"Pub. L. No. 111-2","url":"https://www.govinfo.gov/link/plaw/111/public/2","by":{"1":"18"}},{"t":"reg","label":"45 Fed. Reg. 72,610","url":"https://www.govinfo.gov/link/fr/45/72610","by":{"1":"6, 7"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"ar":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Blonder-Tongue Labs., Inc. v. Univ. of Ill. Found.","cite":"402 U.S. 313","y":1971,"id":"1970/338","sc":1,"sum":"This Court's holding in Triplett v. Lowell, 297 U. S. 638, that a determination of patent invalidity is not res judicata against the patentee in subsequent litigation against a different defendant overruled to the extent that it forecloses an estoppel plea by one facing a charge of infringement of a patent that has once been declared invalid, and in this infringement suit where because of Triplett petitioner did not …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Boys Markets, Inc. v. Retail Clerk’s Union, Local 770","cite":"398 U.S. 235","y":1970,"id":"1969/768","sc":1,"sum":"In the circumstances of this case-where the grievance was subject to arbitration under the collectivebargaining agreement, petitioner was ready for arbitration when the strike was enjoined, and the District Court concluded that respondent's violations of the no-strike clause were causing petitioner irreparable injury--the Norris-LaGuardia Act does not bar the granting of injunctive relief. Sinclair Refining Co. v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"2":"5, 6"}},{"t":"case","label":"Emporium Capwell Co. v. W. Addition Cmty. Org.","cite":"420 U.S. 50","y":1975,"id":"1974/73-696","sc":1,"sum":"Though national labor policy accords the highest priority to nondiscriminatory emWestern Addition Community Organization et al., also on certiorari to the same court. ployment practices, the NLRA does not protect concerted activity by minority employees to bargain with their employer over issues of employment discrimination, thus bypassing their exclusive bargaining representative.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Espinoza v. Montana Dep’t of Rev.","cite":"140 S. Ct. 2246","y":2020,"id":"2019/18-1195","sc":1,"ar":1,"sum":"The Court held a Montana state law that provides funding for education but excludes religious education options violates the Free Exercise Clause of the federal Constitution.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Gamble v. United States","cite":"139 S. Ct. 1960","y":2019,"id":"2018/17-646","sc":1,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"7, 8"}},{"t":"case","label":"Girouard v. United States","cite":"328 U.S. 61","y":1946,"id":"scdb/1945-039","sc":1,"sum":"An alien who is willing to take the oath of allegiance and to serve in the army as a non-combatant but who, because of religious scruples, is unwilling to bear arms in defense of this country may be admitted to citizenship under the Nationality Act of 1940, as amended by the Act of March 27, 1942. United States v. Schwimmer, 279 U. S. 644; United States i'. Macintosh, 283 U. S. 605; and United States v. Bland, 283 …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Helvering v. Hallock","cite":"309 U.S. 106","y":1940,"id":"scdb/1939-097","sc":1,"sum":"1. Decedent in his lifetime created a trust providing that the income from the trust property should be paid to his wife during her lifetime, that upon his death, if she survived him, the corpus of the trust should go to her or to other named beneficiaries, but that upon her death, if he survived, the property should revert to himself. The wife survived. Held, that the value of the remainder interest clearly …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8, 9"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the materiality of falsehood is not an element of the crime of knowingly making a false statement to a federally insured bank. Justice Souter wrote for the court that prosecutors need not prove that a lie was relevant enough to affect the outcome of a bank's decision because the law does not require such materiality.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Wilkins v. United States","cite":"2023 WL 2655449","y":2023,"court":"U.S. Mar. 28","by":{"2":"3, 8"}},{"t":"case","label":"BRIEFS U.S. Br., Fort Bend Cnty. v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"11"}}]};